<?php
session_start();
require_once __DIR__.'/../includes/config.php';
if(empty($_SESSION['admin_logged_in']) || $_SESSION['admin_logged_in']!==true){header('Location: admin-login.php');exit;}
function ah($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$conn->query("CREATE TABLE IF NOT EXISTS rider_payouts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,rider_id INT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NULL,amount DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('pending','approved','paid','cancelled') NOT NULL DEFAULT 'pending',paid_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(rider_id,status),INDEX(order_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['payout_id']??0);$action=$_POST['action']??'';
 if($id<1||!in_array($action,['approve','pay','cancel'],true)){$err='Invalid payout action.';}
 else{
  $new=['approve'=>'approved','pay'=>'paid','cancel'=>'cancelled'][$action];
  $sql=$new==='paid' ? "UPDATE rider_payouts SET status='paid',paid_at=NOW() WHERE id=? AND status IN('approved','pending')" : ($new==='approved' ? "UPDATE rider_payouts SET status='approved' WHERE id=? AND status='pending'" : "UPDATE rider_payouts SET status='cancelled' WHERE id=? AND status IN('pending','approved')");
  $s=$conn->prepare($sql);$s->bind_param('i',$id);$s->execute();$changed=$s->affected_rows;$s->close();
  if($changed)$msg=$new==='paid'?'Payout marked as paid.':ucfirst($new).'.';else$err='Payout status cannot be changed from its current state.';
 }
}
$stats=['pending'=>0,'approved'=>0,'paid'=>0,'cancelled'=>0];$q=$conn->query("SELECT status,COUNT(*) c FROM rider_payouts GROUP BY status");if($q)while($x=$q->fetch_assoc())$stats[$x['status']]=(int)$x['c'];
$rows=[];$sql="SELECT rp.*,r.full_name rider_name,r.phone rider_phone FROM rider_payouts rp LEFT JOIN riders r ON r.id=rp.rider_id ORDER BY rp.id DESC";$q=$conn->query($sql);if($q)while($x=$q->fetch_assoc())$rows[]=$x;
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rider Payouts | Humsafar Admin</title><style>*{box-sizing:border-box}body{margin:0;background:#f7f7f9;color:#222;font:14px Segoe UI,Arial}.page{margin-left:220px;padding:32px;min-height:100vh;max-width:1250px}h1{margin:0;font-size:32px}.sub{color:#777;margin:6px 0 25px}.flash{padding:13px 16px;border-radius:10px;margin-bottom:18px}.ok{background:#eaf9ef;color:#176c36}.bad{background:#fff0f3;color:#b00030}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin-bottom:25px}.stat{background:#fff;border:1px solid #e8e8e8;border-radius:15px;padding:18px}.stat small{color:#888}.stat b{display:block;font-size:24px;margin-top:7px}.card{background:#fff;border:1px solid #e8e8e8;border-radius:16px;overflow:hidden}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:14px;border-bottom:1px solid #eee;text-align:left}.table th{background:#fafafa;color:#777;font-size:12px}.badge{display:inline-block;padding:6px 9px;border-radius:20px;font-size:11px;font-weight:800;background:#fff1dc;color:#8a5a00}.paid{background:#eaf9ef;color:#176c36}.approved{background:#eaf6ff;color:#086d9e}.cancelled{background:#f1f1f1;color:#777}.actions{display:flex;gap:6px}.btn{border:0;border-radius:8px;padding:8px 10px;font-size:11px;font-weight:800;cursor:pointer}.approve{background:#eaf6ff;color:#086d9e}.pay{background:#eaf9ef;color:#176c36}.cancel{background:#fff0f3;color:#b00030}@media(max-width:900px){.page{margin-left:0;padding:20px}.stats{grid-template-columns:1fr 1fr}.table{display:block;overflow:auto;white-space:nowrap}}</style></head><body><?php if(file_exists(__DIR__.'/admin-sidebar.php'))include __DIR__.'/admin-sidebar.php';elseif(file_exists(__DIR__.'/sidebar.php'))include __DIR__.'/sidebar.php';?><main class="page"><h1>Rider Payouts</h1><p class="sub">Every successfully delivered order creates one rider payout using the current Rider Base Payout setting.</p><?php if($msg):?><div class="flash ok"><?=ah($msg)?></div><?php endif;?><?php if($err):?><div class="flash bad"><?=ah($err)?></div><?php endif;?><div class="stats"><div class="stat"><small>Pending</small><b><?=number_format($stats['pending'])?></b></div><div class="stat"><small>Approved</small><b><?=number_format($stats['approved'])?></b></div><div class="stat"><small>Paid</small><b><?=number_format($stats['paid'])?></b></div><div class="stat"><small>Cancelled</small><b><?=number_format($stats['cancelled'])?></b></div></div><div class="card"><table class="table"><tr><th>#</th><th>Rider</th><th>Order</th><th>Amount</th><th>Status</th><th>Created</th><th>Action</th></tr><?php if(!$rows):?><tr><td colspan="7" style="text-align:center;padding:40px;color:#888">No rider payouts yet.</td></tr><?php else:foreach($rows as $x):?><tr><td><?=ah($x['id'])?></td><td><b><?=ah($x['rider_name']?:'Rider #'.$x['rider_id'])?></b><br><small><?=ah($x['rider_phone']?:'')?></small></td><td>#<?=ah($x['order_id'])?></td><td><b>Rs <?=number_format((float)$x['amount'],2)?></b></td><td><span class="badge <?=ah($x['status'])?>"><?=ah(ucfirst($x['status']))?></span></td><td><?=ah(date('d M Y, h:i A',strtotime($x['created_at'])))?></td><td><div class="actions"><?php if($x['status']==='pending'):?><form method="post"><input type="hidden" name="payout_id" value="<?=ah($x['id'])?>"><button class="btn approve" name="action" value="approve">Approve</button></form><?php endif;?><?php if(in_array($x['status'],['pending','approved'],true)):?><form method="post"><input type="hidden" name="payout_id" value="<?=ah($x['id'])?>"><button class="btn pay" name="action" value="pay">Mark Paid</button></form><?php endif;?><?php if(in_array($x['status'],['pending','approved'],true)):?><form method="post"><input type="hidden" name="payout_id" value="<?=ah($x['id'])?>"><button class="btn cancel" name="action" value="cancel">Cancel</button></form><?php endif;?></div></td></tr><?php endforeach;endif;?></table></div></main></body></html>